[CmdletBinding()]
param(
  [string]$CredentialPath = (Join-Path $env:LOCALAPPDATA "hermes\profiles\ervp-orders\secrets\order-completion-api-key.dpapi")
)

$ErrorActionPreference = "Stop"
$scriptPath = Join-Path $PSScriptRoot "sync_order_completion_board.cjs"
Add-Type -AssemblyName System.Security

if (-not (Test-Path -LiteralPath $CredentialPath)) {
  throw "Order Completion credential is not installed for this Windows user."
}
if (-not (Test-Path -LiteralPath $scriptPath)) {
  throw "The branch-independent Order Completion mirror is missing."
}

$protectedBytes = [IO.File]::ReadAllBytes($CredentialPath)
$plainBytes = [System.Security.Cryptography.ProtectedData]::Unprotect(
  $protectedBytes,
  $null,
  [System.Security.Cryptography.DataProtectionScope]::CurrentUser
)
$credentialValue = [Text.Encoding]::UTF8.GetString($plainBytes)
if ($credentialValue -notmatch '^oo_hermes_[A-Za-z0-9_-]{43,112}$') {
  throw "Order Completion credential has an invalid format."
}

$priorCredential = $env:ORDEROPS_API_KEY
try {
  $env:ORDEROPS_API_KEY = $credentialValue
  & node $scriptPath
  if ($LASTEXITCODE -ne 0) {
    throw "Order Completion mirror exited with code $LASTEXITCODE."
  }
} finally {
  if ($null -eq $priorCredential) {
    Remove-Item Env:ORDEROPS_API_KEY -ErrorAction SilentlyContinue
  } else {
    $env:ORDEROPS_API_KEY = $priorCredential
  }
  $credentialValue = $null
  $plainBytes = $null
  $protectedBytes = $null
}
